        for (int k = 0; k < BLOCK_SIZE; ++k) {
            sum += __half2float(As[threadIdx.y][k]) * __half2float(Bs[k][threadIdx.x]);
        }

        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        C[row * ldc + col] = __float2half(sum);
    }
}
