"""
FP16 GEMM for H100 using CUDA
"""
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# All code goes in cuda_sources - kernel + wrapper
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void gemm_kernel(
    const c10::Half* __restrict__ a,
    const c10::Half* __restrict__ b,
    c10::Half* __restrict__ c,
    int m, int n, int k) {

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < m && col < n) {
        float sum = 0.0f;
        for (int i = 0; i < k; i++) {
            sum += (float)a[row * k + i] * (float)b[i * n + col];
        }
        c[row * n + col] = (c10::Half)sum;
    }
}

torch::Tensor gemm_forward(torch::Tensor a, torch::Tensor b) {
    auto c = torch::empty({a.size(0), b.size(1)}, a.options());

    int m = a.size(0);
    int n = b.size(1);
    int k = a.size(1);

    dim3 block(16, 16);
    dim3 grid((n + 15) / 16, (m + 15) / 16);

    gemm_kernel<<<grid, block>>>(
        a.data_ptr<c10::Half>(),
        b.data_ptr<c10::Half>(),
        c.data_ptr<c10::Half>(),
        m, n, k
    );

    return c;
}
"""

module = load_inline(
    name='gemm_ops',
    cpp_sources="",
    cuda_sources=cuda_source,
    functions=['gemm_forward'],
    extra_cuda_cflags=['-O3'],
)

