#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <mma.h>

using namespace nvcuda;

// Block size: 128 threads = 4 warps
// Tile sizes: 64x64 output per block, using 16x16 wmma tiles

#define BLOCK_M 64
#define BLOCK_N 64
#define BLOCK_K 32

__global__ void gemm_kernel(
    const c10::Half* __restrict__ A,
    const c10::Half* __restrict__ B,
    c10::Half* __restrict__ C,
    int M, int N, int K) {

    // Shared memory tiles
    __shared__ half smem_A[BLOCK_M][BLOCK_K];
    __shared__ half smem_B[BLOCK_K][BLOCK_N];

    const int warp_id = threadIdx.x >> 5;  // 0-3
    const int lane_id = threadIdx.x & 31;

    // Block position in output
    const int block_m = blockIdx.y;
    const int block_n = blockIdx.x;

    // Starting rows/cols in global memory
    const int a_row_start = block_m * BLOCK_M;
    const int b_col_start = block_n * BLOCK_N;

    // Each warp handles a 16x64 section (16 rows, all 64 columns)
    // Warps arranged as 4 rows x 1 column
    const int warp_row_offset = warp_id * 16;

    // Accumulator for each warp: 4 WMMA tiles of 16x16 each
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc[4];

    #pragma unroll
    for (int i = 0; i < 4; i++) {
        wmma::fill_fragment(acc[i], 0.0f);
    }

    const int num_k_tiles = (K + BLOCK_K - 1) / BLOCK_K;

    for (int k_tile = 0; k_tile < num_k_tiles; k_tile++) {
        const int k_start = k_tile * BLOCK_K;

        // Collaborative load of A tile (BLOCK_M x BLOCK_K)
        for (int i = threadIdx.x; i < BLOCK_M * BLOCK_K; i += 128) {
            const int row = i / BLOCK_K;
            const int col = i % BLOCK_K;
            const int g_row = a_row_start + row;
            const int g_col = k_start + col;
            half val = __float2half(0.0f);
            if (g_row < M && g_col < K) {
                val = (half)A[g_row * K + g_col];
            }
            smem_A[row][col] = val;
        }

        // Collaborative load of B tile (BLOCK_K x BLOCK_N)
        for (int i = threadIdx.x; i < BLOCK_K * BLOCK_N; i += 128) {
            const int row = i / BLOCK_N;
            const int col = i % BLOCK_N;
            const int g_row = k_start + row;
            const int g_col = b_col_start + col;
            half val = __float2half(0.0f);
            if (g_row < K && g_col < N) {
                val = (half)B[g_row * N + g_col];
            }
            smem_B[row][col] = val;
        }

        __syncthreads();

        // Compute using WMMA
        for (int k_chunk = 0; k_chunk < BLOCK_K; k_chunk += 16) {
            wmma::fragment<wmma::matrix_a, 16, 16, 16, half, wmma::row_major> a_frag;
            wmma::load_matrix_sync(a_frag, &smem_A[warp_row_offset][k_chunk], BLOCK_K);

            #pragma unroll
            for (int col_tile = 0; col_tile < 4; col_tile++) {
                wmma::fragment<wmma::matrix_b, 16, 16, 16, half, wmma::row_major> b_frag;
                wmma::load_matrix_sync(b_frag, &smem_B[k_chunk][col_tile * 16], BLOCK_N);
                wmma::mma_sync(acc[col_tile], a_frag, b_frag, acc[col_tile]);
            }
        }

        __syncthreads();
    }

    // Store results - convert FP32 accumulator to FP16 output
    const int c_row_start = a_row_start;
    const int c_col_start = b_col_start;

    // Simpler approach: store FP32 to shared memory, then convert and write
    __shared__ float smem_C[BLOCK_M][BLOCK_N];

    #pragma unroll
    for (int col_tile = 0; col_tile < 4; col_tile++) {
        const int tile_row = warp_row_offset;
        const int tile_col = col_tile * 16;
        wmma::store_matrix_sync(&smem_C[tile_row][tile_col], acc[col_tile], BLOCK_N, wmma::mem_row_major);
    }

    __syncthreads();

    // Convert and write to global memory
    for (int i = threadIdx.x; i < BLOCK_M * BLOCK_N; i += 128) {
        const int row = i / BLOCK_N;
        const int col = i % BLOCK_N;
        const int g_row = c_row_start + row;
        const int g_col = c_col_start + col;
        if (g_row < M && g_col < N) {
            C[g_row * N + g_col] = __float2half(smem_C[row][col]);
        }
    }
}

