#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <mma.h>

using namespace nvcuda;

#define BLOCK_M 64
#define BLOCK_N 64
#define BLOCK_K 32
#define NUM_STAGES 2  // Double buffering

__global__ void gemm_kernel(
    const c10::Half* __restrict__ A,
    const c10::Half* __restrict__ B,
    c10::Half* __restrict__ C,
    int M, int N, int K) {

    // Double-buffered shared memory tiles
    __shared__ half smem_A[NUM_STAGES][BLOCK_M][BLOCK_K];
    __shared__ half smem_B[NUM_STAGES][BLOCK_K][BLOCK_N];

    const int warp_id = threadIdx.x >> 5;
    const int lane_id = threadIdx.x & 31;

    const int block_m = blockIdx.y;
    const int block_n = blockIdx.x;

    const int a_row_start = block_m * BLOCK_M;
    const int b_col_start = block_n * BLOCK_N;
    const int warp_row_offset = warp_id * 16;

    // Accumulators
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc[4];
    #pragma unroll
    for (int i = 0; i < 4; i++) {
        wmma::fill_fragment(acc[i], 0.0f);
    }

    const int num_k_tiles = (K + BLOCK_K - 1) / BLOCK_K;
    int load_stage = 0;
    int compute_stage = 0;

    // Prefetch first tile
    {
        const int k_start = 0;
        #pragma unroll
        for (int i = threadIdx.x; i < BLOCK_M * BLOCK_K; i += 128) {
            const int row = i / BLOCK_K, col = i % BLOCK_K;
            const int g_row = a_row_start + row, g_col = k_start + col;
            smem_A[load_stage][row][col] = (g_row < M && g_col < K) ? (half)A[g_row * K + g_col] : __float2half(0.0f);
        }
        #pragma unroll
        for (int i = threadIdx.x; i < BLOCK_K * BLOCK_N; i += 128) {
            const int row = i / BLOCK_N, col = i % BLOCK_N;
            const int g_row = k_start + row, g_col = b_col_start + col;
            smem_B[load_stage][row][col] = (g_row < K && g_col < N) ? (half)B[g_row * N + g_col] : __float2half(0.0f);
        }
        __syncthreads();
    }

    // Main loop with double buffering
    for (int k_tile = 0; k_tile < num_k_tiles; k_tile++) {
        compute_stage = k_tile % NUM_STAGES;

        // Compute current tile while loading next
        if (k_tile + 1 < num_k_tiles) {
            const int k_next = (k_tile + 1) * BLOCK_K;
            load_stage = (k_tile + 1) % NUM_STAGES;

            // Asynchronous loads would be better, but using simple approach for now
            for (int i = threadIdx.x; i < BLOCK_M * BLOCK_K; i += 128) {
                const int row = i / BLOCK_K, col = i % BLOCK_K;
                const int g_row = a_row_start + row, g_col = k_next + col;
                smem_A[load_stage][row][col] = (g_row < M && g_col < K) ? (half)A[g_row * K + g_col] : __float2half(0.0f);
            }
            for (int i = threadIdx.x; i < BLOCK_K * BLOCK_N; i += 128) {
                const int row = i / BLOCK_N, col = i % BLOCK_N;
                const int g_row = k_next + row, g_col = b_col_start + col;
                smem_B[load_stage][row][col] = (g_row < K && g_col < N) ? (half)B[g_row * N + g_col] : __float2half(0.0f);
            }
        }

        // Compute using WMMA
        for (int k_chunk = 0; k_chunk < BLOCK_K; k_chunk += 16) {
            wmma::fragment<wmma::matrix_a, 16, 16, 16, half, wmma::row_major> a_frag;
            wmma::load_matrix_sync(a_frag, &smem_A[compute_stage][warp_row_offset][k_chunk], BLOCK_K);

            #pragma unroll
            for (int col_tile = 0; col_tile < 4; col_tile++) {
                wmma::fragment<wmma::matrix_b, 16, 16, 16, half, wmma::row_major> b_frag;
                wmma::load_matrix_sync(b_frag, &smem_B[compute_stage][k_chunk][col_tile * 16], BLOCK_N);
                wmma::mma_sync(acc[col_tile], a_frag, b_frag, acc[col_tile]);
            }
        }

